assign projectsoc_reset = (projectsoc_soc_rst | projectsoc_cpu_rst);
assign crg_stop = gw2ddrphy_stop0;
assign crg_reset0 = gw2ddrphy_reset0;
assign {led0, led1, led2, led3, led4, led5} = (~led_logical);
assign button_pressed = (~{btn_n3, btn_n2, btn_n1, btn_n0});
always @(*) begin
    crg_rst = 1'd0;
    if (projectsoc_soc_rst) begin
        crg_rst = 1'd1;
    end
end
assign projectsoc_bus_error = error;
always @(*) begin
    projectsoc_interrupt = 32'd0;
    projectsoc_interrupt[1] = projectsoc_timer_irq;
