//------------------------------------------------------------------------------
// Memory rom: 8192-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [31:0] rom[0:8191];
initial begin
	$readmemh("ddr_diagnosis_rom.init", rom);
end
reg [31:0] rom_dat0;
always @(posedge sys_clk) begin
	rom_dat0 <= rom[projectsoc_projectsoc_adr];
end
assign projectsoc_projectsoc_dat_r = rom_dat0;


//------------------------------------------------------------------------------
// Memory sram: 2048-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: Sync | Mode: Read-First  | Write-Granularity: 8
reg [31:0] sram[0:2047];
initial begin
	$readmemh("ddr_diagnosis_sram.init", sram);
end
reg [31:0] sram_dat0;
always @(posedge sys_clk) begin : mem_write_block
	integer we_index;
	for(we_index = 0; we_index < 4; we_index=we_index+1)
		if (projectsoc_ram_we0[we_index])
			sram[projectsoc_ram_adr0][we_index*8 +: 8] <= projectsoc_ram_dat_w0[we_index*8 +: 8];
	sram_dat0 <= sram[projectsoc_ram_adr0];
end
assign projectsoc_ram_dat_r0 = sram_dat0;


//------------------------------------------------------------------------------
// Memory mem: 29-words x 8-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [7:0] mem[0:28];
initial begin
	$readmemh("ddr_diagnosis_mem.init", mem);
end
reg [7:0] mem_dat0;
always @(posedge sys_clk) begin
	mem_dat0 <= mem[csr_bankarray_adr];
end
assign csr_bankarray_dat_r = mem_dat0;


//------------------------------------------------------------------------------
// Memory storage: 16-words x 10-bit
//------------------------------------------------------------------------------
// Port 0 | Read: ----  | Write: Sync | Mode: Read-First 
// Port 1 | Read: Sync  | Write: ---- | 
reg [9:0] storage[0:15];
reg [9:0] storage_dat1;
always @(posedge sys_clk) begin
	if (projectsoc_uart_core_tx_fifo_wrport_we)
		storage[projectsoc_uart_core_tx_fifo_wrport_adr] <= projectsoc_uart_core_tx_fifo_wrport_dat_w;
end
always @(posedge sys_clk) begin
	if (projectsoc_uart_core_tx_fifo_rdport_re) begin
		storage_dat1 <= storage[projectsoc_uart_core_tx_fifo_rdport_adr];
	end
end
assign projectsoc_uart_core_tx_fifo_rdport_dat_r = storage_dat1;


//------------------------------------------------------------------------------
